using System;
using Didionysymus.Lattice.Runtime;
using Didionysymus.Lattice.Runtime.Unity;
using UnityEngine;

namespace Didionysymus.Lattice.Tests.Runtime.Fixtures
{
    /// <summary>
    /// Helpers for the manifest tests: add a manifest generated by discovery's rules, one filled with chosen entries,
    /// or one never generated; add an automatic host that waits for activation; build a region resolver. Internal
    /// because <see cref="ManifestCoverage"/> is.
    /// </summary>
    internal static class ManifestTestKit
    {
        /// <summary>
        /// Adds an <see cref="InjectionManifest"/> to <paramref name="unit"/> and fills it with
        /// <see cref="ComponentDiscovery.Generate"/>.
        /// </summary>
        /// <param name="unit">The GameObject the manifest sits on: a host's for scene coverage, a root's for hierarchy coverage.</param>
        /// <param name="coverage">The walk the manifest describes.</param>
        /// <returns>The generated manifest.</returns>
        internal static InjectionManifest AddGenerated(GameObject unit, ManifestCoverage coverage)
        {
            InjectionManifest manifest = unit.AddComponent<InjectionManifest>();
            ComponentDiscovery.Generate(manifest, coverage);
            return manifest;
        }

        /// <summary>
        /// Adds an <see cref="InjectionManifest"/> to <paramref name="unit"/> holding exactly the given entries, the
        /// given coverage, the current format and no hosts, whatever discovery would find.
        /// </summary>
        /// <param name="unit">The GameObject the manifest sits on.</param>
        /// <param name="coverage">The coverage written, which may be a value no generation writes.</param>
        /// <param name="inject">The entries of the inject list, in order.</param>
        /// <param name="initialize">The entries of the initialize list, in order.</param>
        /// <returns>The filled manifest.</returns>
        internal static InjectionManifest AddWithContent(
            GameObject unit,
            ManifestCoverage coverage,
            MonoBehaviour[] inject,
            MonoBehaviour[] initialize
        )
        {
            InjectionManifest manifest = unit.AddComponent<InjectionManifest>();
            InjectionTargets targets = new InjectionTargets();
            targets.Inject.AddRange(inject);
            targets.Initialize.AddRange(initialize);
            manifest.SetContent(coverage, targets, Array.Empty<MonoBehaviour>());
            return manifest;
        }

        /// <summary>
        /// Adds an <see cref="InjectionManifest"/> to <paramref name="unit"/> and nothing else, so it keeps format 0:
        /// never generated.
        /// </summary>
        /// <param name="unit">The GameObject the manifest sits on.</param>
        /// <returns>The never-generated manifest.</returns>
        internal static InjectionManifest AddNeverGenerated(GameObject unit)
        {
            return unit.AddComponent<InjectionManifest>();
        }

        /// <summary>
        /// Creates a tracked, inactive scene root named <paramref name="name"/> and adds a <see cref="TestRootScope"/>
        /// to it, so its <c>Awake</c>, and with it the prepare, waits until the test activates the GameObject.
        /// </summary>
        /// <param name="bed">The bed that tracks the GameObject.</param>
        /// <param name="name">The GameObject's name.</param>
        /// <returns>The host, not yet awake.</returns>
        internal static TestRootScope AddInactiveHost(SceneTestBed bed, string name)
        {
            GameObject gameObject = bed.Create(name, null);
            gameObject.SetActive(false);
            return gameObject.AddComponent<TestRootScope>();
        }

        /// <summary>
        /// Builds a region resolver that registers <see cref="IPlayModeService"/> as a Singleton, tracked so the bed
        /// disposes it.
        /// </summary>
        /// <param name="bed">The bed that tracks the resolver.</param>
        /// <returns>The new region resolver, not yet initialized.</returns>
        internal static IObjectResolver CreateRegion(SceneTestBed bed)
        {
            return bed.Track(Container.Build(b => b.Register<IPlayModeService, PlayModeService>(Lifetime.Singleton)));
        }
    }
}
